SELECT s.id AS sessionId, s.agent_id AS agentId, d.name AS agentName, s.title AS title, s.user_id AS userId, a.username AS username, a.real_name AS realName, m.role AS role, m.content AS content, m.message_type AS messageType, m.create_time AS createTime FROM tbl_data_chat_session s LEFT JOIN tbl_data_chat_message m ON s.id = m.session_id INNER JOIN tbl_platform_account_info a ON a.id = s.user_id LEFT JOIN tbl_data_agent d ON d.id = s.agent_id
s.status != 'deleted'
AND s.agent_id = #{query.agentId}
AND s.user_id = #{query.userId}
AND s.title LIKE CONCAT('%', #{query.title}, '%')
AND m.role = #{query.role}
AND m.message_type = #{query.messageType}
AND m.content LIKE CONCAT('%', #{query.content}, '%')
AND (s.title LIKE CONCAT('%', #{query.keyword}, '%') OR m.content LIKE CONCAT('%', #{query.keyword}, '%') OR a.username LIKE CONCAT('%', #{query.keyword}, '%') OR a.real_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND m.create_time >= #{query.startTime}::timestamp
AND m.create_time <= #{query.endTime}::timestamp
ORDER BY m.create_time DESC LIMIT #{limit} OFFSET #{offset}

